with gaps as (select *, case when lag(started_at) over (partition by country order by started_at, id) is null or started_at > lag(started_at) over (partition by country order by started_at, id) + interval 90 days then 1 else 0 end as is_new_burst from sessions) select id, customer_id, browser, started_at, country, sum(is_new_burst) over (partition by country order by started_at, id rows between unbounded preceding and current row) as session_id from gaps;
